// CollaborationServiceHandler is an implementation of the elephant.collab.v1.CollaborationService
// service.
type CollaborationServiceHandler interface {
	// Collaborate is the live editing path: one stream carries any
	// number of document subscriptions, keyed on the doc field of
	// every message. It is the Connect counterpart of the WebSocket at
	// GET /collab/socket and shares its implementation; the two differ
	// only in framing and in how a connection-wide refusal is
	// delivered (see CollaborateResponse.close).
	//
	// Requires HTTP/2. Auth: the bearer on the request opens the
	// stream; per-document permission is resolved on Subscribe exactly
	// as on the WebSocket (editors need w, observers r). The stream
	// ends with unauthenticated when the bearer expires without an
	// AuthRefresh, with resource_exhausted on the rate limit or the
	// subscription cap, and with invalid_argument on an oversized
	// payload; the structured reason is in the error metadata under
	// "reason" and matches the collab_rejections_total vocabulary.
	Collaborate(context.Context, *connect.BidiStream[v1.CollaborateRequest, v1.CollaborateResponse]) error
	// Snapshot materializes the live Y.Doc state for a document into
	// a new published version in the repository. The collab service
	// performs the Y.Doc → NewsDoc translation, runs Documents.Validate
	// against the materialized document, and forwards the result to
	// Documents.Update using the lock token from doc_lock_state.
	//
	// Returns FailedPrecondition with error metadata
	//   freshness_violation_at: <RFC3339 timestamp>
	//   server_state_vector: <base64>
	// when if_state_vector_at_least is not dominated by the server's
	// state vector at snapshot time.
	Snapshot(context.Context, *connect.Request[v1.SnapshotRequest]) (*connect.Response[v1.SnapshotResponse], error)
	// BeginPublish takes the publish soft-stop: client updates for the
	// doc are rejected with publish_in_progress until the soft-stop
	// is resolved (consumed by a freezing Snapshot, dropped by
	// CancelPublish, or expired by the worker). Awareness keeps
	// flowing. Required precondition for a freezing Snapshot.
	BeginPublish(context.Context, *connect.Request[v1.BeginPublishRequest]) (*connect.Response[v1.BeginPublishResponse], error)
	// CancelPublish drops an in-flight soft-stop owned by the caller.
	// Returns OK whether or not a row existed; failing-closed on a
	// mismatched owner is FailedPrecondition.
	CancelPublish(context.Context, *connect.Request[v1.CancelPublishRequest]) (*connect.Response[v1.CancelPublishResponse], error)
	// InspectNamedDocument returns the current state of a named
	// document, materialized as JSON by walking the Yjs tree
	// (YMap → object, YArray → array, string → string). The state
	// is materialized live (snapshot + stream replay).
	//
	// Auth: any authenticated caller may inspect a service-managed
	// doc or their own user-scoped doc. Inspecting another user's
	// user-scoped doc requires the doc_admin scope.
	InspectNamedDocument(context.Context, *connect.Request[v1.InspectNamedDocumentRequest]) (*connect.Response[v1.InspectNamedDocumentResponse], error)
	// InspectDocument returns the current live collaborative state of a
	// repository document, materialized as JSON by walking the Yjs tree
	// (the same walk InspectNamedDocument uses). Unlike Snapshot, this
	// is a read-only debugging view: it does NOT translate to a NewsDoc,
	// write a version, or strip the application-private _collab key — it
	// shows the raw Y.Doc the collab service is currently serving.
	//
	// The state is rebuilt live (per-session replay-cache snapshot +
	// Redis stream tail), exactly as Snapshot rebuilds it. A repository
	// doc only has collaborative state while a session holds it; when no
	// session is active the response carries live=false and empty state
	// rather than an error (read the canonical version from the
	// repository in that case).
	//
	// Auth: collab_admin scope OR repository 'w' on doc_id — the same
	// gate as GetCollaborativeStateSnapshot.
	InspectDocument(context.Context, *connect.Request[v1.InspectDocumentRequest]) (*connect.Response[v1.InspectDocumentResponse], error)
	// ResetCollaborativeState force-evicts the current session for
	// a doc and forces subscribers back to the canonical repository
	// version. Used as an escape hatch when live Yjs state has
	// diverged from a working state (frontend bug, corrupted update
	// sequence) and clients can't recover normally. Data loss is the
	// explicit price: anything in the live state that hasn't been
	// materialized to a repository version is gone.
	//
	// Auth: 'w' permission on the doc (same gate as writing — anyone
	// who can write is trusted to manage its session lifecycle).
	//
	// Fails with FailedPrecondition + error metadata when the doc is
	// currently frozen; callers should redirect to unfreeze in that
	// case. Idempotent: calling reset on a doc with no active session
	// returns success with an empty aborted_session_id.
	ResetCollaborativeState(context.Context, *connect.Request[v1.ResetCollaborativeStateRequest]) (*connect.Response[v1.ResetCollaborativeStateResponse], error)
	// Unfreeze clears the frozen_docs row for a doc (if any) and
	// records an explicit_unfreeze_marks row attributed to the
	// caller. The mark is what prevents the subscribe-time
	// auto-freeze (see freeze_on_workflow_states on subscribe) from
	// immediately re-freezing the doc on the next subscribe.
	//
	// Idempotent: calling Unfreeze on a doc that isn't frozen still
	// upserts the unfreeze mark — preemptive unfreeze is the migration
	// UX (the user clicks "open for collaborative editing" before any
	// subscribe has triggered the auto-freeze gate).
	//
	// Auth: 'w' permission on the doc (anyone trusted to write is
	// trusted to gate collaborative-editing access).
	Unfreeze(context.Context, *connect.Request[v1.UnfreezeRequest]) (*connect.Response[v1.UnfreezeResponse], error)
	// ListCollaborativeSessions returns metadata for the
	// collaborative sessions on a doc, newest first. Paginated.
	// Includes closed, active, and purged sessions; purged sessions
	// carry tombstone fields with content-bearing fields nulled.
	//
	// Auth: collab_admin scope OR repository `w` on doc_id (the
	// same gate Subscribe uses — "if you can participate, you can
	// see what happened in past sessions on this doc").
	ListCollaborativeSessions(context.Context, *connect.Request[v1.ListCollaborativeSessionsRequest]) (*connect.Response[v1.ListCollaborativeSessionsResponse], error)
	// GetCollaborativeSession returns the full metadata for a single
	// session by ID: the session row plus the repository versions
	// created during it and the participants who joined.
	//
	// Auth: collab_admin scope OR repository `w` on the session's
	// doc_id. The session row is resolved before the auth check;
	// unknown session_id returns NotFound to any authenticated caller.
	GetCollaborativeSession(context.Context, *connect.Request[v1.GetCollaborativeSessionRequest]) (*connect.Response[v1.GetCollaborativeSessionResponse], error)
	// ListActiveCollaborativeSessions returns currently-active
	// sessions (closed_at IS NULL). Optional doc_id narrows the
	// result to a single doc.
	//
	// Auth: with doc_id, collab_admin scope OR repository `w` on
	// doc_id. Without doc_id (fleet-wide listing) collab_admin is
	// required — there's no per-doc anchor for the replay-aligned
	// check.
	ListActiveCollaborativeSessions(context.Context, *connect.Request[v1.ListActiveCollaborativeSessionsRequest]) (*connect.Response[v1.ListActiveCollaborativeSessionsResponse], error)
	// GetCollaborativeStateSnapshot returns a union of "everything the
	// collab service currently knows about doc X" — the doc's active
	// session if any, frozen-doc state, explicit unfreeze mark,
	// pending-publish soft-stop, Redis stream metadata, and recent
	// archive chunk info.
	//
	// Read-only and lock-free; the response is a moment-in-time view
	// that may be inconsistent in the strict sense (e.g. the active
	// session might have evicted between two reads), which is fine
	// for debugging use.
	//
	// Works on any doc kind. For named docs the frozen, unfreeze, and
	// pending_publish fields are always null.
	//
	// Auth: repository-backed doc_id — collab_admin scope OR
	// repository `w` on doc_id. Named-doc IDs (__presence__,
	// __user:…) require collab_admin since they don't route through
	// a repository ACL.
	GetCollaborativeStateSnapshot(context.Context, *connect.Request[v1.GetCollaborativeStateSnapshotRequest]) (*connect.Response[v1.GetCollaborativeStateSnapshotResponse], error)
	// PurgeCollaborativeSession permanently deletes the S3 content
	// (manifest.json, updates/*.bin, closed.json) for a single
	// collaborative session and tombstones the corresponding Postgres
	// row. A tombstone.json is written to S3 in place of the deleted
	// artifacts so future audit queries can distinguish "this session
	// never existed" from "this session was purged on date Y."
	//
	// Destructive and irreversible. The repository's document
	// versions are NOT touched — the caller is responsible for any
	// upstream deletion if the legal request requires it.
	//
	// Auth: data_purge scope (separate from collab_admin since
	// destruction shouldn't be bundled with read access).
	PurgeCollaborativeSession(context.Context, *connect.Request[v1.PurgeCollaborativeSessionRequest]) (*connect.Response[v1.PurgeCollaborativeSessionResponse], error)
	// PurgeDocumentSessions purges every collaborative session for a
	// single document. Same semantics as PurgeCollaborativeSession,
	// applied in a loop. Returns the count of sessions actually
	// purged.
	//
	// Auth: data_purge scope.
	PurgeDocumentSessions(context.Context, *connect.Request[v1.PurgeDocumentSessionsRequest]) (*connect.Response[v1.PurgeDocumentSessionsResponse], error)
	// GetSessionUpdates returns a page of the session's archived
	// update log. Each record carries the raw Yjs update bytes plus
	// origination metadata; decoding the update body is the caller's
	// problem (callers may want "render a diff" or "feed to a Yjs
	// replay tool" and a bake-in decode policy would be wrong here).
	//
	// For an active session, returns updates up to the most recent
	// archive checkpoint; updates that have arrived at the collab
	// service but not yet flushed to S3 are not visible. For a purged
	// session, returns an empty result with purged=true.
	//
	// Auth: collab_admin scope OR repository `w` on the session's
	// doc_id (resolved by loading the session row before the auth
	// check).
	GetSessionUpdates(context.Context, *connect.Request[v1.GetSessionUpdatesRequest]) (*connect.Response[v1.GetSessionUpdatesResponse], error)
	// StreamSessionUpdates streams the session's archived update log
	// from the caller's cursor to the most recent archive checkpoint,
	// and then ends: the records GetSessionUpdates pages through,
	// without the pages. It does not follow a live session past the
	// checkpoint.
	//
	// A purged session yields a single message with purged=true and no
	// record. Every refusal — authorization, the arguments, a
	// time-anchored cursor that would scan past the chunk ceiling —
	// comes before the first message, so it is the call's status. Once
	// records are flowing the stream ends with unauthenticated when the
	// caller's token expires and with unavailable when the serving pod
	// shuts down; either way the client resumes with after_redis_id set
	// to the last redis_id it received.
	//
	// Auth: collab_admin scope OR repository `w` on the session's
	// doc_id, the same gate as GetSessionUpdates.
	StreamSessionUpdates(context.Context, *connect.Request[v1.StreamSessionUpdatesRequest], *connect.ServerStream[v1.StreamSessionUpdatesResponse]) error
	// CreateSketch creates a new document sketch: a collaborative
	// document that exists before its underlying repository document
	// does. The caller may supply a UUID on the starting document
	// (taken as-is after the repository conflict check) or leave it
	// empty (the service generates a v4 UUID). The repository must
	// not already have a doc with the resolved UUID; collisions are
	// rejected with AlreadyExists.
	//
	// Auth: doc_write scope (mirrors the repository's create gate).
	CreateSketch(context.Context, *connect.Request[v1.CreateSketchRequest]) (*connect.Response[v1.CreateSketchResponse], error)
	// UpdateSketchACL replaces the sketch's ACL in full. `w` gates
	// editing (editor subscribe, forward, edit ACL, discard); `r`
	// grants observer subscribe, and is also carried over when the
	// sketch
	// is promoted to a repository document.
	//
	// Auth: `w` on the sketch's current ACL.
	UpdateSketchACL(context.Context, *connect.Request[v1.UpdateSketchACLRequest]) (*connect.Response[v1.UpdateSketchACLResponse], error)
	// DiscardSketch abandons a sketch: closes any active session,
	// drops the Redis stream, deletes the sketch row. Idempotent on
	// a missing sketch (returns success).
	//
	// Auth: `w` on the sketch's ACL.
	DiscardSketch(context.Context, *connect.Request[v1.DiscardSketchRequest]) (*connect.Response[v1.DiscardSketchResponse], error)
	// ListSketches returns summaries of sketches the caller has
	// access to. By default returns sketches the caller owns; with
	// `shared=true` returns sketches the caller has been granted
	// `w` on by someone else.
	//
	// Auth: authenticated; results are ACL-filtered server-side.
	ListSketches(context.Context, *connect.Request[v1.ListSketchesRequest]) (*connect.Response[v1.ListSketchesResponse], error)
	// GetSketch returns a sketch's summary and its last saved content.
	// The document is the last materialised copy of the collaborative
	// state: exact for a sketch with no open session, and up to the
	// auto-snapshot interval behind while one is being edited. It is
	// not a substitute for subscribing. Reading it opens no session,
	// takes no lock and leaves updated_at untouched.
	//
	// Auth: `r` or `w` on the sketch's ACL, OR collab_admin scope.
	GetSketch(context.Context, *connect.Request[v1.GetSketchRequest]) (*connect.Response[v1.GetSketchResponse], error)
	// BulkSnapshot mirrors the repository's BulkUpdate: a list of
	// SnapshotRequests forwarded as a single repository.BulkUpdate
	// for atomic multi-document semantics. Mixed bulks (sketches +
	// repo docs in the same call) are supported; each entry is
	// classified independently by the collab service. Freezing is not
	// supported in a bulk: an entry with freeze=true is rejected with
	// InvalidArgument.
	BulkSnapshot(context.Context, *connect.Request[v1.BulkSnapshotRequest]) (*connect.Response[v1.BulkSnapshotResponse], error)
	// GetSessionVersionAnchors returns the (version, redis_id,
	// received_at) anchors for the repository versions produced during
	// a session. Used by the replay UI to mark "we are now at version
	// N" as the user scrubs through the session's update stream.
	//
	// Auth: collab_admin scope OR repository `w` on the session's
	// doc_id (same as the other session-scoped replay RPCs).
	//
	// Legacy session_versions rows written before the redis_id column
	// existed have an empty redis_id; the response carries them as-is
	// so callers can render the version pill at session start and not
	// at the precise scrubber moment.
	GetSessionVersionAnchors(context.Context, *connect.Request[v1.GetSessionVersionAnchorsRequest]) (*connect.Response[v1.GetSessionVersionAnchorsResponse], error)
	// GetDocumentTimeline returns a merged, chronologically-ordered
	// (newest-first) timeline of repository versions and collaborative
	// sessions for a single document. The collab service composes the
	// response from Documents.GetHistory (forwarded with the caller's
	// bearer) and the local sessions tables; the
	// `produced_by_session_id` cross-link is set from
	// collaborative_session_versions so the UI doesn't have to do an
	// N+1 to associate versions with the session that produced them.
	//
	// Auth: collab_admin scope OR repository `w` on doc_id (same as
	// the other doc-scoped replay RPCs). The inner Documents.GetHistory
	// call is forwarded with the caller's bearer for defence-in-depth
	// — the repository re-checks reachability on its side.
	GetDocumentTimeline(context.Context, *connect.Request[v1.GetDocumentTimelineRequest]) (*connect.Response[v1.GetDocumentTimelineResponse], error)
}

